// Read domains from SSL_DOMAINS env (comma-separated). Emit one item per domain.

const raw = $env.SSL_DOMAINS || '';
const domains = raw.split(',').map(d => d.trim()).filter(Boolean);

if (domains.length === 0) {
  return [{ json: { skipped: true, reason: 'no domains configured' } }];
}

return domains.map(d => ({ json: { domain: d } }));

// TLS-connect to the domain, read the peer certificate, compute days_until_expiry.
// Three-tier alert: warning (<30 days), urgent (<14 days), critical (<7 days).
//
// Default rejectUnauthorized=true (CA-validated). Set
// SSL_ACCEPT_SELFSIGNED=1 to opt in to inspecting self-signed / chain-broken
// certs (useful for staging or internal mTLS endpoints where you want to
// monitor expiry even if the cert chain does not validate).

const tls = require('tls');

const domain = $input.first().json.domain;
const host = domain.replace(/^https?:\/\//, '').split('/')[0].split(':')[0];
const port = 443;
const acceptSelfSigned = $env.SSL_ACCEPT_SELFSIGNED === '1';

function connect() {
  return new Promise((resolve, reject) => {
    const socket = tls.connect({
      host,
      port,
      servername: host,
      timeout: 10000,
      rejectUnauthorized: !acceptSelfSigned,
    }, () => {
      const cert = socket.getPeerCertificate();
      socket.end();
      if (!cert || !cert.valid_to) {
        reject(new Error('No peer certificate or no valid_to'));
      } else {
        resolve(cert);
      }
    });
    socket.on('error', reject);
    socket.on('timeout', () => {
      socket.destroy();
      reject(new Error('TLS connection timeout'));
    });
  });
}

let cert;
try {
  cert = await connect();
} catch (e) {
  return [{ json: {
    domain,
    host,
    error: true,
    errorMessage: e.message,
    severity: 'error',
    shouldAlert: true,
    checkedAt: new Date().toISOString(),
  } }];
}

const expiryDate = new Date(cert.valid_to);
const now = Date.now();
const daysLeft = Math.floor((expiryDate.getTime() - now) / (1000 * 60 * 60 * 24));

let severity = 'ok';
let shouldAlert = false;
if (daysLeft < 7) { severity = 'critical'; shouldAlert = true; }
else if (daysLeft < 14) { severity = 'urgent'; shouldAlert = true; }
else if (daysLeft < 30) { severity = 'warning'; shouldAlert = true; }

return [{ json: {
  domain,
  host,
  daysLeft,
  expiryDate: expiryDate.toISOString().slice(0, 10),
  issuer: (cert.issuer && cert.issuer.O) || 'unknown',
  subject: (cert.subject && cert.subject.CN) || host,
  severity,
  shouldAlert,
  checkedAt: new Date().toISOString(),
} }];

// Build a severity-coded Slack Block Kit message.

const e = $input.first().json;

const emoji = {
  warning: ':warning:',
  urgent: ':alarm_clock:',
  critical: ':rotating_light:',
  error: ':boom:',
}[e.severity] || ':bell:';

const color = {
  warning: '#daa038',
  urgent: '#d93f0b',
  critical: '#a30200',
  error: '#666666',
}[e.severity] || '#666666';

const headline = e.error
  ? `${emoji} SSL check failed for ${e.domain}: ${e.errorMessage || 'unknown error'}`
  : `${emoji} ${e.severity.toUpperCase()}: ${e.domain} expires in ${e.daysLeft} days`;

const blocks = [
  { type: 'section', text: { type: 'mrkdwn', text: `*${headline}*` } },
];

if (!e.error) {
  blocks.push({
    type: 'section',
    fields: [
      { type: 'mrkdwn', text: `Expires: *${e.expiryDate}*` },
      { type: 'mrkdwn', text: `Issuer: *${e.issuer}*` },
      { type: 'mrkdwn', text: `Days left: *${e.daysLeft}*` },
      { type: 'mrkdwn', text: `Subject: *${e.subject}*` },
    ],
  });
}

blocks.push({
  type: 'context',
  elements: [{ type: 'mrkdwn', text: `Checked at ${e.checkedAt}` }],
});

return [{ json: {
  text: headline,
  attachments: [{ color, blocks }],
} }];

// Fallback for Slack delivery failure. Log structured error.
const err = ($input.first().json && $input.first().json.error) || {};
return [{ json: {
  ok: false,
  fallback: true,
  errorMessage: err.message || 'slack delivery failed',
  loggedAt: new Date().toISOString(),
} }];
